static struct flash_info * sst25l_match_device ( struct spi_device * spi ) { struct flash_info * flash_info = NULL ; struct spi_message m ; struct spi_transfer t ; unsigned char cmd_resp [ 6 ] ; int i , err ; uint16_t id ; spi_message_init ( & m ) ; memset ( & t , 0 , sizeof ( spi_transfer ) ) ; cmd_resp [ 0 ] = SST25L_CMD_READ_ID ; cmd_resp [ 1 ] = 0 ; cmd_resp [ 2 ] = 0 ; cmd_resp [ 3 ] = 0 ; cmd_resp [ 4 ] = 0xff ; cmd_resp [ 5 ] = 0xff ; t . tx_buf = cmd_resp ; t . rx_buf = cmd_resp ; t . len = sizeof ( cmd_resp ) ; spi_message_add_tail ( & t , & m ) ; err = spi_sync ( spi , & m ) ; id = ( cmd_resp [ 4 ] << 8 ) | cmd_resp [ 5 ] ; for ( i = 0 ; i < ARRAY_SIZE ( sst25l_flash_info ) ; i ++ ) { if ( sst25l_flash_info [ i ] . device_id == id ) { flash_info = & sst25l_flash_info [ i ] ; } } if ( ! flash_info ) { dev_err ( & spi -> dev , "unknown id %.4x\n" , id ) ; } return flash_info ; } 